package ec.edu.unl.sec.identityaccess.domain;
import java.time.Instant;import java.util.*;
public record AccessIdentity(UUID id,String login,String displayName,Type type,boolean active,long revision,Instant createdAt){public AccessIdentity{Objects.requireNonNull(id);login=normalize(login);if(displayName==null||displayName.isBlank())throw new IllegalArgumentException("displayName required");Objects.requireNonNull(type);Objects.requireNonNull(createdAt);if(revision<0)throw new IllegalArgumentException("revision");}public static String normalize(String v){if(v==null)throw new IllegalArgumentException("login required");String n=v.strip().toLowerCase(Locale.ROOT);if(n.isEmpty()||n.length()>254)throw new IllegalArgumentException("invalid login");return n;}public enum Type{HUMAN,TECHNICAL}}
